// A fresh UUID every run, so turn 2 can never pass on a stale session.
const uuid = 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, (c) => {
  const r = Math.floor(Math.random() * 16);
  const v = c === 'x' ? r : ((r & 0x3) | 0x8);
  return v.toString(16);
});

return [{ json: { session_id: uuid } }];

// R-1 passes only if BOTH are true:
//   1. n8n reached the bridge at all          -> connectivity
//   2. turn 2 remembered turn 1's number      -> session continuity through n8n
// Turn 2 must also report resumed:true - that is the bridge choosing --resume over --session-id.

const turn2 = $input.first().json;
const turn1 = $('Bridge - Turn 1').first().json;

const output = String(turn2.output || '');
const remembered = /\b7\b/.test(output);

const checks = {
  connectivity: turn1.ok === true,
  session_created: turn1.resumed === false,
  session_resumed: turn2.resumed === true,
  remembered_the_number: remembered,
};

const passed = Object.values(checks).every(Boolean);

return [{
  json: {
    R1_RESULT: passed ? 'PASS' : 'FAIL',
    checks,
    session_id: turn2.session_id,
    turn1_output: String(turn1.output || '').slice(0, 200),
    turn2_output: output.slice(0, 200),
  },
}];
